# Let's write a small C# program to parse the binlog
mkdir -p /tmp/binlog-reader && cat > /tmp/binlog-reader/Program.cs << 'EOF'
using System;
using System.IO;
using Microsoft.Build.Logging.StructuredLogger;
using Microsoft.Build.Framework;

class Program
{
    static void Main(string[] args)
    {
        var binlogPath = args[0];
        var buildRoot = BinaryLog.ReadBuild(binlogPath);

        Console.WriteLine("=== BUILD ERRORS ===");
        var errors = new List<(string project, string code, string message, string file, int line)>();

        buildRoot.VisitAllChildren<Error>(error =>
        {
            var project = GetParentProject(error);
            errors.Add((project, error.Code ?? "", error.Text ?? error.ToString(), error.File ?? "", error.LineNumber));
        });

        foreach (var g in errors.GroupBy(e => e.project))
        {
            Console.WriteLine($"\n--- Project: {g.Key} ---");
            foreach (var e in g)
            {
                Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.message}");
            }
        }

        Console.WriteLine("\n\n=== BUILD WARNINGS (first 30) ===");
        int warnCount = 0;
        buildRoot.VisitAllChildren<Warning>(warning =>
        {
            if (warnCount++ < 30)
            {
                var project = GetParentProject(warning);
                Console.WriteLine($"  [{warning.Code}] {project}: {warning.Text}");
            }
        });

        Console.WriteLine($"\n\n=== FAILED PROJECTS ===");
        buildRoot.VisitAllChildren<Project>(project =>
        {
            if (!project.Succeeded)
            {
                Console.WriteLine($"  FAILED: {project.Name} ({project.ProjectFile})");
            }
        });
    }

    static string GetParentProject(BaseNode node)
    {
        var current = node.Parent;
        while (current != null)
        {
            if (current is Project p) return Path.GetFileName(p.ProjectFile ?? p.Name);
            if (current is Target t && t.Parent is Project tp) return Path.GetFileName(tp.ProjectFile ?? tp.Name);
            current = current.Parent;
        }
        return "<unknown>";
    }
}
EOF

