using System;
using System.IO;
using Microsoft.Build.Logging.StructuredLogger;

class Program2
{
    static void Main(string[] args)
    {
        var binlogPath = args[0];
        var buildRoot = BinaryLog.ReadBuild(binlogPath);

        // Look at project references and package references
        Console.WriteLine("=== SEARCHING FOR PROJECT STRUCTURE ===");
        buildRoot.VisitAllChildren<Message>(msg =>
        {
            var text = msg.Text ?? "";
            if (text.Contains("Newtonsoft") || text.Contains("PackageReference") || text.Contains("Services.csproj"))
            {
                if (text.Length < 500)
                    Console.WriteLine($"  MSG: {text}");
            }
        });

        Console.WriteLine("\n=== LOOKING AT ITEMS/METADATA ===");
        buildRoot.VisitAllChildren<Item>(item =>
        {
            var text = item.ToString() ?? "";
            if (text.Contains("Newtonsoft") || text.Contains("PackageReference"))
            {
                Console.WriteLine($"  ITEM: {text}");
            }
        });

        Console.WriteLine("\n=== NAMED NODES ===");
        buildRoot.VisitAllChildren<NamedNode>(node =>
        {
            if ((node.Name ?? "").Contains("Newtonsoft"))
                Console.WriteLine($"  NODE[{node.GetType().Name}]: {node.Name}");
        });
    }
}
EOF

