using System;
using System.IO;
using Microsoft.Build.Logging.StructuredLogger;

class Program2
{
    static void Main(string[] args)
    {
        var binlogPath = args[0];
        var buildRoot = BinaryLog.ReadBuild(binlogPath);

        // Get all AddItem for PackageReference
        Console.WriteLine("=== PACKAGE REFERENCES (AddItem) ===");
        buildRoot.VisitAllChildren<AddItem>(item =>
        {
            if (item.Name == "PackageReference")
            {
                var project = GetParentProject(item);
                foreach (var child in item.Children)
                {
                    Console.WriteLine($"  {project}: {child}");
                }
            }
        });

        // Check for restore warnings/errors
        Console.WriteLine("\n=== RESTORE MESSAGES ===");
        buildRoot.VisitAllChildren<Message>(msg =>
        {
            var text = msg.Text ?? "";
            if (text.Contains("NU1") || text.Contains("warning NU") || text.Contains("error NU"))
                Console.WriteLine($"  {text}");
        });

        Console.WriteLine("\n=== ALL WARNINGS ===");
        buildRoot.VisitAllChildren<Warning>(w =>
        {
            Console.WriteLine($"  [{w.Code}] {w.Text}");
        });

        // Look at the source file content
        Console.WriteLine("\n=== SOURCE FILES REFERENCED ===");
        buildRoot.VisitAllChildren<Message>(msg =>
        {
            var text = msg.Text ?? "";
            if (text.Contains("UserService.cs"))
                Console.WriteLine($"  {text}");
        });
    }

    static string GetParentProject(BaseNode node)
    {
