using System;
using System.IO;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

class Program2
{
    static void Main(string[] args)
    {
        var binlogPath = args[0];
        var buildRoot = BinaryLog.ReadBuild(binlogPath);

        // Look at all children recursively of Services.csproj evaluation
        buildRoot.VisitAllChildren<ProjectEvaluation>(eval =>
        {
            if (!eval.Name.Contains("Services")) return;
            Console.WriteLine($"=== Evaluation: {eval.Name} ===");
            PrintTree(eval, 0, 4);
        });
    }

    static void PrintTree(BaseNode node, int depth, int maxDepth)
    {
        if (depth > maxDepth) return;
        var indent = new string(' ', depth * 2);
        var name = node switch {
            NamedNode n => $"[{node.GetType().Name}] {n.Name}",
            _ => $"[{node.GetType().Name}] {node}"
        };

        // Filter to interesting items
        var text = node.ToString() ?? "";
        if (depth <= 2 || text.Contains("Package") || text.Contains("Newtonsoft") || text.Contains("ProjectReference"))
        {
            Console.WriteLine($"{indent}{name}");
        }

        if (node.HasChildren)
        {
            foreach (var child in node.Children.OfType<BaseNode>())
            {
                PrintTree(child, depth + 1, maxDepth);
            }
        }
    }
}
