using System;
using System.IO;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

class Program2
{
    static void Main(string[] args)
    {
        var binlogPath = args[0];
        var buildRoot = BinaryLog.ReadBuild(binlogPath);

        // Check the restore output - did NuGet restore actually resolve packages for Services?
        Console.WriteLine("=== NuGet Restore details for Services ===");
        buildRoot.VisitAllChildren<Message>(msg =>
        {
            var text = msg.Text ?? "";
            if ((text.Contains("Services") && text.Contains("package")) ||
                text.Contains("Newtonsoft.Json") ||
                (text.Contains("PackageReference") && text.Contains("Services")))
            {
                if (text.Length < 300)
                    Console.WriteLine($"  {text}");
            }
        });

        // Check the project build - what targets ran for Services.csproj
        Console.WriteLine("\n=== Projects in build ===");
        buildRoot.VisitAllChildren<Project>(proj =>
        {
            Console.WriteLine($"  Project: {proj.Name} | SourceFile: {proj.ProjectFile}");
        });

        // Look for ResolvePackageAssets or similar target
        Console.WriteLine("\n=== Targets in Services build ===");
        buildRoot.VisitAllChildren<Project>(proj =>
        {
            if (proj.Name != "Services.csproj") return;
            foreach (var child in proj.Children.OfType<Target>())
            {
                if (child.Name.Contains("Package") || child.Name.Contains("Reference") || child.Name.Contains("Resolve"))
                    Console.WriteLine($"  Target: {child.Name}");
            }
        });

        // Check assets file
        Console.WriteLine("\n=== assets/lock file messages ===");
        buildRoot.VisitAllChildren<Message>(msg =>
        {
            var text = msg.Text ?? "";
            if (text.Contains("project.assets.json") || text.Contains("packages.lock"))
            {
                if (text.Length < 300)
                    Console.WriteLine($"  {text}");
            }
        });
    }
}
